-- examples/input-2.ts: canCreateTodo()
CREATE OR REPLACE FUNCTION app.can_create_todo(
  plan text,
  count integer
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
  RETURN plan <> 'free' OR count < 3;
END;
$$;

-- examples/input-2.ts: canCreateTodoWithType()
CREATE OR REPLACE FUNCTION app.can_create_todo_with_type(
  sub app.subscription,
  count integer
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  plan text;
BEGIN
  plan := (sub).plan;
  IF plan = 'free' THEN
    RETURN count <= 3;
  END IF;
  IF plan = 'pro' THEN
    RETURN count <= 6;
  END IF;
  RETURN count <= 9;
END;
$$;

