-- examples/input-1.ts: isNotEmpty()
CREATE OR REPLACE FUNCTION app.is_not_empty(
  string text
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
  IF string IS NULL THEN
    RETURN false;
  END IF;
  RETURN string IS DISTINCT FROM '';
END;
$$;

-- examples/input-1.ts: priceCents()
CREATE OR REPLACE FUNCTION app.price_cents(
  list_cents integer,
  percent_off double precision
)
RETURNS double precision
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  discount double precision;
BEGIN
  discount := COALESCE(percent_off, 0);
  RETURN list_cents * (100 - discount) / 100;
END;
$$;

